SUPPORT = {"Written interview": "የጽሑፍ ቃለ መጠይቅ", "Flexible hours": "ተለዋዋጭ ሰዓት", "Written instructions": "የጽሑፍ መመሪያ", "Step-free workplace": "ደረጃ የሌለበት የሥራ ቦታ"}


def localized_jobs(jobs):
    return {job.id: dict(zip(("title", "organization", "summary", "responsibilities"), JOB_TEXT[job.id]),
                         support=[SUPPORT[item] for item in job.support]) for job in jobs}
